"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

export default function Header() {
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 40);
        };

        window.addEventListener("scroll", handleScroll);

        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <header
            className={`
        fixed top-0 left-0 w-full z-50
        transition-all duration-300
        ${scrolled
                    ? "bg-light dark:bg-dark border-b border-light-border dark:border-dark-muted backdrop-blur"
                    : "bg-transparent"
                }
      `}
        >
            <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">

                {/* Logo */}
                <Link
                    href="/"
                    className="text-xl font-semibold text-text-dark dark:text-offwhite"
                >
                    Brand
                </Link>

                {/* Navigation */}
                <nav className="hidden md:flex items-center gap-8">

                    <Link
                        href="#services"
                        className="text-text-muted dark:text-gray hover:text-orange transition"
                    >
                        Services
                    </Link>

                    <Link
                        href="#how-we-work"
                        className="text-text-muted dark:text-gray hover:text-orange transition"
                    >
                        How We Work
                    </Link>

                    <Link
                        href="#models"
                        className="text-text-muted dark:text-gray hover:text-orange transition"
                    >
                        Models
                    </Link>

                    <Link
                        href="#why-nearshore"
                        className="text-text-muted dark:text-gray hover:text-orange transition"
                    >
                        Why Nearshore
                    </Link>

                    <Link
                        href="#contact"
                        className="text-text-muted dark:text-gray hover:text-orange transition"
                    >
                        Contact
                    </Link>

                </nav>

                {/* CTA */}
                <button className="bg-orange text-white px-5 py-2 rounded-pill hover:bg-orange-light transition">
                    Get Started
                </button>

            </div>
        </header>
    );
}